package com.workworth.earnings.application;
import com.workworth.earnings.domain.EarningStatus; import com.workworth.earnings.persistence.*; import com.workworth.salary.application.MonthlySalaryRateService; import com.workworth.salary.domain.MonthlySalaryRate; import com.workworth.workday.application.WorkdayService; import com.workworth.workday.persistence.Workday; import java.math.*; import java.time.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EarningMaterializationService { private final WorkdayEarningRepository earnings; private final WorkdayService workdays; private final MonthlySalaryRateService rates; private final Clock clock; public EarningMaterializationService(WorkdayEarningRepository e,WorkdayService w,MonthlySalaryRateService r,Clock c){earnings=e;workdays=w;rates=r;clock=c;}
 @Transactional public WorkdayEarning materialize(Workday day){return earnings.findByWorkdayId(day.getId()).orElseGet(()->create(day));}
 private WorkdayEarning create(Workday day){long seconds=workdays.time(day); try {MonthlySalaryRate r=rates.getRate(YearMonth.from(day.getLocalDate())); BigDecimal amount=r.hourlyNetRate().multiply(BigDecimal.valueOf(seconds)).divide(BigDecimal.valueOf(3600),12,RoundingMode.HALF_UP); return earnings.save(new WorkdayEarning(day.getId(),day.getLocalDate(),EarningStatus.AVAILABLE,seconds,amount,r.salaryProfileId(),r.incomeSource(),r.monthlyNetIncome(),r.annualNetIncome(),r.payPeriods(),r.currencyCode(),r.standardEconomicHours(),r.hourlyNetRate(),clock.instant()));} catch(RuntimeException ex){return earnings.save(new WorkdayEarning(day.getId(),day.getLocalDate(),EarningStatus.UNAVAILABLE,seconds,null,null,null,null,null,0,null,null,null,clock.instant()));}}
}
